import java.util.concurrent.*;
import java.util.concurrent.Flow.*;
import java.util.concurrent.SubmissionPublisher;

class MockSample32 {
    static class PrintSubscriber implements Subscriber<String> {
        private final String name;
        private Subscription subscription;

        PrintSubscriber(String name) {
            this.name = name;
        }

        public void onSubscribe(Subscription subscription) {
            this.subscription = subscription;
            subscription.request(Long.MAX_VALUE);
        }

        public void onNext(String item) {
            System.out.print(name + ":" + item + " ");
        }

        public void onError(Throwable throwable) {
            System.out.print("error ");
        }

        public void onComplete() {
            System.out.print(name + ":done ");
        }
    }

    public static void main(String[] args) throws Exception {
        try (SubmissionPublisher<String> publisher =
                 new SubmissionPublisher<>()) {

            publisher.subscribe(new PrintSubscriber("A"));
            publisher.subscribe(new PrintSubscriber("B"));

            publisher.submit("x");
            publisher.close();

            Thread.sleep(500);
        }
    }
}

